```js
import { Controller } from "@hotwired/stimulus"
import { differenceInDays, secondsToDate } from "helpers/date_helpers"

const DEFAULT_LOCALE = "en-US"

// Dates read the locale the person chose on the server, which the layout
// publishes in <html lang>.
const documentLocale = () => document.documentElement.lang || DEFAULT_LOCALE

export default class extends Controller {
  ...
  initialize() {
    const locale = documentLocale()
    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
    ...
    this.agoFormatter = new AgoFormatter(locale)
    this.daysagoFormatter = new DaysAgoFormatter(locale)
    this.indaysFormatter = new InDaysFormatter(locale)
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(locale)
    this.timeordateFormatter = new TimeOrDateFormatter(locale)
  }
```

For AgoFormatter: use Intl.RelativeTimeFormat with numeric: "auto":
```js
class AgoFormatter {
  constructor(locale) { this.#formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" }) }
  format(dt) {
    const seconds = (Date.now() - dt.getTime()) / 1000
    ...
    if (years >= 1) return this.#formatter.format(-Math.floor(years), "year")
    ...
    return this.#formatter.format(-seconds, "second")  // "just now" / "30秒前"
  }
}
```
