# I18n from reporting it as missing.
write_locale(:en, TRANSLATIONS.to_h { |key, value| [ key, english_for(key, value) ] })

japanese = TRANSLATIONS.to_h { |key, value| [ key, japanese_for(key, value) ] }
japanese.merge!(RAILS_LOCALE) { |key, _text, _rails| raise "Key #{key.inspect} collides with the Rails locale tree" }
write_locale(:ja, japanese)

